\set ON_ERROR_STOP on
begin;
create temp table checks(label text);
grant select,insert on checks to anon,authenticated,service_role;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label; end if; insert into checks values(label); end$$;
create function pg_temp.denied(q text,code text,label text) returns void language plpgsql as $$begin begin execute q; exception when others then if sqlstate=code then perform pg_temp.ok(true,label); return; end if; raise; end; raise exception 'FAIL: % allowed',label; end$$;
do $$begin
  if to_regprocedure('public.revoke_whatsapp_promotion(text)') is null then raise exception 'FAIL: preference RPC missing'; end if;
end$$;
do $$declare
  u uuid:='bbbbbbbb-0000-0000-0000-000000000001'; other_unit uuid:='bbbbbbbb-0000-0000-0000-000000000002'; ub uuid:='bbbbbbbb-0000-0000-0000-000000000003';
  c uuid:='cccccccc-0000-0000-0000-000000000001'; cb uuid:='cccccccc-0000-0000-0000-000000000002';
  a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); bb uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); actor uuid:=gen_random_uuid();
  voucher uuid:=gen_random_uuid(); v2 uuid:=gen_random_uuid(); vb uuid:=gen_random_uuid(); v3 uuid:=gen_random_uuid(); c3 uuid:=gen_random_uuid(); j uuid; j2 uuid; jb uuid; j3 uuid; f uuid; f2 uuid; fb uuid; f3 uuid; cost uuid;
  x jsonb; dto jsonb; before_state jsonb; after_state jsonb; revision bigint; e bigint; old_window timestamptz; n integer;
begin
  insert into auth.users(id) values(actor); insert into public.platform_admins values(actor);
  insert into public.platform_flags(key,value) values('whatsapp_automation_dispatch','true') on conflict(key) do update set value=excluded.value;
  update public.whatsapp_channels set last_health_check_at=clock_timestamp() where unit_id in(u,ub);
  insert into public.whatsapp_template_accounts(id,organization_id,waba_id,verified_at) values(a,'aaaaaaaa-0000-0000-0000-000000000001','2912345',clock_timestamp());
  insert into public.whatsapp_template_bindings(id,unit_id,channel_id,provider,account_id,verified_at) values(b,u,'dddddddd-0000-0000-0000-000000000001','datafy',a,clock_timestamp()),(bb,ub,'dddddddd-0000-0000-0000-000000000003','zapi',null,clock_timestamp());
  perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',actor)::text,true);
  update public.whatsapp_template_bindings set adopted_at=clock_timestamp(),dispatch_enabled=true where id in(b,bb);
  insert into public.whatsapp_remote_templates(id,account_id,logical_id,version,language,name,desired_hash,requested_category,binding_generation) values(t,a,'mkt_voucher_programado_v1',1,'pt_BR','mkt_voucher_programado_v1',repeat('a',64),'MARKETING',1);
  x:=public.begin_whatsapp_template_sync(a);
  perform pg_temp.ok(public.publish_whatsapp_template_sync(a,1,x->'templates',jsonb_build_array(jsonb_build_object('id',t,'remote_id','remote29','name','mkt_voucher_programado_v1','language','pt_BR','observed_hash',repeat('a',64),'effective_category','MARKETING','remote_status','APPROVED','quality','GREEN'))),'current marketing GET approved');
  select sync_epoch into e from public.whatsapp_remote_templates where id=t;
  insert into public.vouchers(id,unit_id,customer_id) values(voucher,u,c),(v2,u,c),(vb,ub,cb);
  j:=public.enqueue_whatsapp_automation(jsonb_build_object('unit_id',u,'kind','voucher_issued','voucher_id',voucher,'source_event_key','preferences29','fact_at',clock_timestamp(),'expires_at',clock_timestamp()+interval '1 day'));
  j2:=public.enqueue_whatsapp_automation(jsonb_build_object('unit_id',u,'kind','voucher_issued','voucher_id',v2,'source_event_key','preferences29','fact_at',clock_timestamp(),'expires_at',clock_timestamp()+interval '1 day'));
  jb:=public.enqueue_whatsapp_automation(jsonb_build_object('unit_id',ub,'kind','voucher_issued','voucher_id',vb,'source_event_key','preferences29','fact_at',clock_timestamp(),'expires_at',clock_timestamp()+interval '1 day'));
  perform pg_temp.ok(public.get_whatsapp_promotion_preference(j)='{"decision":"unknown","revision":null}'::jsonb,'unknown no implicit opt-in');
  perform pg_temp.ok(not public.issue_whatsapp_preference_token(j,repeat('1',64)),'unknown cannot issue capability');
  x:=public.claim_whatsapp_automation(j); f:=(x->>'claim_token')::uuid;
  update public.whatsapp_automation_jobs set safe_log_body='Fake Original Name voucher link [preference_token]' where id=j;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j,f,1,null,e),'unknown blocks actual prepare');
  perform pg_temp.ok((select attempts=0 and posting_started_at is null from public.whatsapp_automation_jobs where id=j),'blocked consent consumed no POST');
  insert into public.whatsapp_message_consent_events(unit_id,customer_id,purpose,decision,source_code,evidence_reference,observed_at) values(u,c,'promotional','opt_in','individual_proof','fixture-proof',clock_timestamp()),(other_unit,c,'promotional','opt_in','individual_proof','fixture-proof-other',clock_timestamp());
  perform pg_temp.ok(public.requeue_whatsapp_automation(j),'corrected blocked job requeues');
  perform pg_temp.ok(public.issue_whatsapp_preference_token(j,repeat('1',64)),'hash capability derives job scope');
  perform pg_temp.ok((select expires_at=created_at+interval '90 days' and unit_id=u and customer_id=c from public.whatsapp_message_preference_tokens where token_hash=repeat('1',64)),'SQL90days and derived unit/customer');
  before_state:=jsonb_build_object('tokens',(select jsonb_agg(to_jsonb(z)) from public.whatsapp_message_preference_tokens z),'consent',(select jsonb_agg(to_jsonb(z)) from public.whatsapp_message_consent_events z),'jobs',(select jsonb_agg(to_jsonb(z)) from public.whatsapp_automation_jobs z),'customer',(select to_jsonb(z) from public.customers z where id=c),'slots',(select jsonb_agg(to_jsonb(z)) from public.whatsapp_promotion_slots z));
  dto:=public.lookup_whatsapp_preference_token(repeat('1',64));
  after_state:=jsonb_build_object('tokens',(select jsonb_agg(to_jsonb(z)) from public.whatsapp_message_preference_tokens z),'consent',(select jsonb_agg(to_jsonb(z)) from public.whatsapp_message_consent_events z),'jobs',(select jsonb_agg(to_jsonb(z)) from public.whatsapp_automation_jobs z),'customer',(select to_jsonb(z) from public.customers z where id=c),'slots',(select jsonb_agg(to_jsonb(z)) from public.whatsapp_promotion_slots z));
  perform pg_temp.ok(dto=jsonb_build_object('valid',true,'unitLabel','A1','choice','opt_in'),'GET minimal label/valid/choice only');
  perform pg_temp.ok(before_state=after_state,'GET no domain mutation');
  update public.customers set do_not_contact=true where id=c;
  perform pg_temp.ok(not public.issue_whatsapp_preference_token(j,repeat('2',64)),'DNC prohibits new token');
  perform pg_temp.ok(public.revoke_whatsapp_promotion(repeat('1',64)),'public refusal still valid when globally DNC');
  perform pg_temp.ok((select do_not_contact from public.customers where id=c),'opt-out preserves global DNC');
  perform pg_temp.ok(public.revoke_whatsapp_promotion(repeat('1',64)),'repeat POST idempotent');
  perform pg_temp.ok((select count(*)=2 from public.whatsapp_message_consent_events where unit_id=u and customer_id=c and purpose='promotional'),'repeat creates no evidence');
  perform pg_temp.ok((select decision='opt_in' from public.whatsapp_message_consent_events where unit_id=other_unit and customer_id=c),'unit opt-out preserves sister preference');
  perform pg_temp.ok((select revoked_at is null from public.whatsapp_message_preference_tokens where token_hash=repeat('1',64)),'token capability not one-use');
  update public.customers set do_not_contact=false where id=c;
  insert into public.whatsapp_message_consent_events(unit_id,customer_id,purpose,decision,source_code,evidence_reference,observed_at) values(u,c,'promotional','opt_in','individual_proof','later-proof',clock_timestamp()-interval '10 years');
  perform pg_temp.ok(public.revoke_whatsapp_promotion(repeat('1',64)),'still-valid link opts out after legitimate opt-in');
  perform pg_temp.ok((public.get_whatsapp_promotion_preference(j)->>'revision')::bigint=4,'revision SQL monotonic despite old observedAt');
  perform pg_temp.ok(public.invalidate_whatsapp_preference_token(repeat('1',64)),'internal explicit capability revocation');
  perform pg_temp.ok(public.lookup_whatsapp_preference_token(repeat('1',64)) is null and not public.revoke_whatsapp_promotion(repeat('1',64)),'revoked uniform invalid');
  perform pg_temp.ok(public.lookup_whatsapp_preference_token(repeat('f',64)) is null and not public.revoke_whatsapp_promotion(repeat('f',64)),'unknown uniform invalid');
  insert into public.whatsapp_message_preference_tokens(unit_id,customer_id,token_hash,created_at,expires_at) values(u,c,repeat('e',64),clock_timestamp()-interval '91 days',clock_timestamp()-interval '1 day');
  perform pg_temp.ok(public.lookup_whatsapp_preference_token(repeat('e',64)) is null and not public.revoke_whatsapp_promotion(repeat('e',64)),'expired uniform invalid');
  insert into public.whatsapp_message_consent_events(unit_id,customer_id,purpose,decision,source_code,evidence_reference,observed_at) values(u,c,'promotional','opt_in','individual_proof','latest-proof',clock_timestamp());
  revision:=(public.get_whatsapp_promotion_preference(j)->>'revision')::bigint;
  x:=public.claim_whatsapp_automation(j); f:=(x->>'claim_token')::uuid;
  insert into public.whatsapp_template_cost_authorizations(account_id,binding_id,binding_generation,category,valid_from,valid_until,actor_id) values(a,b,1,'MARKETING',clock_timestamp()-interval '2 days',clock_timestamp()-interval '1 day',actor);
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j,f,1,revision,e),'official marketing requires real cost permission');
  perform pg_temp.ok((select error_code='cost_not_authorized' from public.whatsapp_automation_jobs where id=j),'cost reason closed');
  insert into public.whatsapp_template_cost_authorizations(account_id,binding_id,binding_generation,category,valid_from,valid_until,actor_id) values(a,b,1,'MARKETING',clock_timestamp()-interval '1 minute',clock_timestamp()+interval '1 day',actor) returning id into cost;
  perform pg_temp.ok(public.requeue_whatsapp_automation(j),'cost corrected requeue');
  x:=public.claim_whatsapp_automation(j); f:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(j,f,1,revision,e),'marketing prepare current consent and cost');
  perform pg_temp.ok((select cost_authorization_id=cost and attempts=1 from public.whatsapp_automation_jobs where id=j),'real cost pinned at POST');
  perform pg_temp.ok((select state='reserved' and window_days=7 from public.whatsapp_promotion_slots where job_id=j),'provisional slot captures seven days');
  perform pg_temp.denied(format('update public.whatsapp_automation_jobs set customer_id=null,safe_log_body=null,customer_erased_at=clock_timestamp() where id=%L',j),'23514','live customer cannot forge erasure of reference/render');
  perform pg_temp.denied(format('update public.whatsapp_automation_jobs set safe_log_body=null where id=%L',j),'23514','posted live render cannot be erased without customer erasure');
  -- Documented nonacceptance releases the actual promotional slot atomically.
  insert into public.customers(id,organization_id,name,phone) values(c3,'aaaaaaaa-0000-0000-0000-000000000001','Promotion reject fixture','55999990029');
  insert into public.vouchers(id,unit_id,customer_id) values(v3,u,c3);
  insert into public.whatsapp_message_consent_events(unit_id,customer_id,purpose,decision,source_code,evidence_reference,observed_at) values(u,c3,'promotional','opt_in','individual_proof','reject-proof',clock_timestamp());
  j3:=public.enqueue_whatsapp_automation(jsonb_build_object('unit_id',u,'kind','voucher_issued','voucher_id',v3,'source_event_key','preferences29-reject','fact_at',clock_timestamp(),'expires_at',clock_timestamp()+interval '1 day'));
  x:=public.claim_whatsapp_automation(j3); f3:=(x->>'claim_token')::uuid;update public.whatsapp_automation_jobs set safe_log_body='Reject safe render' where id=j3;
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(j3,f3,1,1,e),'second contact own promotional slot');
  perform pg_temp.ok(public.finish_whatsapp_automation(j3,f3,'{"outcome":"rejected","reason":"documented_preproxy_429"}'),'documented promotional429 definite nonacceptance');
  perform pg_temp.ok(not exists(select from public.whatsapp_promotion_slots where job_id=j3),'definite429 releases actual promotional slot');
  perform pg_temp.ok((select state='retry_wait' and attempts=1 and posting_started_at is null and safe_log_body is null from public.whatsapp_automation_jobs where id=j3),'definite429 retains network attempt backoff and logical identity');
  perform pg_temp.denied(format('delete from public.whatsapp_promotion_slots where job_id=%L',j),'23514','direct service cannot release live slot');
  x:=public.claim_whatsapp_automation(j2); f2:=(x->>'claim_token')::uuid; update public.whatsapp_automation_jobs set safe_log_body='second promotional render' where id=j2;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f2,1,revision,e),'second promotion blocked by slot');
  update public.whatsapp_automation_jobs set claimed_until=clock_timestamp()-interval '1 second' where id=j;
  update public.whatsapp_promotion_slots set claimed_until=clock_timestamp()-interval '1 second' where job_id=j;
  perform pg_temp.ok(public.requeue_whatsapp_automation(j2),'second re-evaluation allowed');
  x:=public.claim_whatsapp_automation(j2); f2:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f2,1,revision,e),'expired posting lease never reclaims reserved slot');
  perform pg_temp.ok(not public.finish_whatsapp_automation(j,f,'{"outcome":"local_preflight_refused","reason":"final_consent_changed"}'),'expired local reset forbidden');
  update app_private.whatsapp_promotion_policy set window_days=1;
  perform pg_temp.ok(public.finish_whatsapp_automation(j,f,'{"outcome":"uncertain","reason":"post_ambiguous"}'),'uncertain extends captured slot');
  select window_until into old_window from public.whatsapp_promotion_slots where job_id=j;
  perform pg_temp.ok(old_window>=clock_timestamp()+interval '6 days 23 hours' and (select window_days=7 from public.whatsapp_promotion_slots where job_id=j),'new policy never shortens captured slot');
  perform pg_temp.ok(not public.finish_whatsapp_automation(j,f,'{"outcome":"rejected","reason":"documented_preproxy_429"}'),'uncertain cannot release');
  update public.whatsapp_template_bindings set generation=generation+1,dispatch_enabled=false where id=b;
  perform pg_temp.ok(public.finish_whatsapp_automation(j,f,'{"outcome":"accepted","reason":"provider_accepted","provider_message_id":"late29"}'),'late acceptance preserves historical pin after binding change');
  perform pg_temp.ok((select state='accepted' and window_until>=old_window and window_days=7 from public.whatsapp_promotion_slots where job_id=j),'late acceptance monotonic window');
  perform pg_temp.ok(not public.issue_whatsapp_preference_token(j,repeat('3',64)),'accepted no new token');
  -- Adopted nonofficial promotion needs consent and slot, never fake WABA/cost/epoch.
  insert into public.whatsapp_message_consent_events(unit_id,customer_id,purpose,decision,source_code,evidence_reference,observed_at) values(ub,cb,'promotional','opt_in','individual_proof','text-proof',clock_timestamp());
  revision:=(public.get_whatsapp_promotion_preference(jb)->>'revision')::bigint;
  x:=public.claim_whatsapp_automation(jb); fb:=(x->>'claim_token')::uuid; update public.whatsapp_automation_jobs set safe_log_body='Fake Original Name text promotion' where id=jb;
  perform pg_temp.ok(public.issue_whatsapp_preference_token(jb,repeat('4',64)),'text capability derived scope');
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(jb,fb,1,revision,null),'text promotion consent slot no WABA');
  perform pg_temp.ok((select window_days=1 from public.whatsapp_promotion_slots where job_id=jb),'new slot captures current policy');
  perform pg_temp.denied(format('update public.whatsapp_automation_jobs set posting_started_at=null,claim_token=null,claimed_until=null,state=''blocked'',attempts=0,error_code=''final_consent_changed'' where id=%L',jb),'23514','direct reset cannot forge local refusal');
  perform pg_temp.denied(format('select public.finish_whatsapp_automation(%L,%L,''{"outcome":"local_preflight_refused","reason":"arbitrary"}'')',jb,fb),'22023','local reason closed');
  perform pg_temp.denied(format('select public.finish_whatsapp_automation(%L,%L,''{"outcome":"local_preflight_refused","reason":"final_consent_changed","postAttempted":false}'')',jb,fb),'22023','no caller evidence flag accepted');
  perform pg_temp.ok(public.finish_whatsapp_automation(jb,fb,'{"outcome":"local_preflight_refused","reason":"final_consent_changed"}'),'live zero POST local refusal');
  perform pg_temp.ok((select state='blocked' and attempts=0 and safe_log_body is null and posting_started_at is null and claim_token is null and claimed_until is null from public.whatsapp_automation_jobs where id=jb),'zero POST clears only prepared attempt');
  perform pg_temp.ok(not exists(select from public.whatsapp_promotion_slots where job_id=jb),'zero POST releases provisional slot');
  perform pg_temp.ok((select count(*)=0 from app_private.whatsapp_post_reset_permits) and (select count(*)=0 from app_private.whatsapp_promotion_slot_release_permits),'one-use permits consumed');
  perform pg_temp.ok(public.requeue_whatsapp_automation(jb),'local block corrected requeue');
  x:=public.claim_whatsapp_automation(jb); fb:=(x->>'claim_token')::uuid;update public.whatsapp_automation_jobs set safe_log_body='Fake Original Name text promotion' where id=jb;
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(jb,fb,1,revision,null),'text retry same identity new fence');
  perform pg_temp.ok(public.finish_whatsapp_automation(jb,fb,'{"outcome":"uncertain","reason":"post_ambiguous"}'),'generic timeout conserves slot');
  perform pg_temp.ok(not public.finish_whatsapp_automation(jb,fb,'{"outcome":"local_preflight_refused","reason":"final_consent_changed"}'),'uncertain forbids zero POST reset');
  update public.customers set deleted_at=clock_timestamp() where id=cb;
  perform pg_temp.ok(not exists(select from public.whatsapp_message_consent_events where customer_id=cb) and not exists(select from public.whatsapp_message_preference_tokens where customer_id=cb) and not exists(select from public.whatsapp_promotion_slots where customer_id=cb),'erasure removes personal preference rows');
  perform pg_temp.ok((select state='uncertain' and safe_log_body is null and customer_id is null and customer_erased_at is not null and claim_token=fb and posting_started_at is not null from public.whatsapp_automation_jobs where id=jb),'erasure keeps technical uncertain identity only');
  perform pg_temp.ok(public.lookup_whatsapp_preference_token(repeat('4',64)) is null and not public.revoke_whatsapp_promotion(repeat('4',64)),'erased token uniform invalid');
  perform pg_temp.ok(public.finish_whatsapp_automation(jb,fb,'{"outcome":"accepted","reason":"provider_accepted","provider_message_id":"erased-late29"}'),'erased late acceptance technical evidence');
  perform pg_temp.ok((select provider_message_id='erased-late29' and safe_log_body is null and customer_id is null from public.whatsapp_automation_jobs where id=jb),'late acceptance never restores personal rows');
  perform pg_temp.denied(format('update public.whatsapp_automation_jobs set safe_log_body=''Fake Original Name'' where id=%L',jb),'23514','erased render never restored');
  update public.customers set deleted_at=clock_timestamp() where id=c;
  perform pg_temp.ok((select safe_log_body is null and state='accepted' and provider_message_id='late29' from public.whatsapp_automation_jobs where id=j),'already accepted render erased correlation retained');
  perform pg_temp.ok((select state='blocked' and customer_id is null and safe_log_body is null from public.whatsapp_automation_jobs where id=j2),'unposted erased job blocked');
  perform pg_temp.ok(not exists(select from public.whatsapp_automation_jobs where safe_log_body like '%Fake Original Name%'),'fake name absent internal render');
  perform pg_temp.ok(not exists(select from information_schema.columns where table_schema='public' and table_name='whatsapp_message_preference_tokens' and column_name in('token','raw_token')),'new token store hash only');
  for n in 1..30 loop perform pg_temp.ok(public.check_whatsapp_preference_rate(repeat('9',64)),'rate request '||n); end loop;
  perform pg_temp.ok(not public.check_whatsapp_preference_rate(repeat('9',64)),'atomic rate limit30/60');
  update app_private.whatsapp_preference_rate_buckets set expires_at=clock_timestamp()-interval '6 minutes' where bucket_hash=repeat('9',64);
  perform pg_temp.ok(public.check_whatsapp_preference_rate(repeat('8',64)),'new technical bucket');
  perform pg_temp.ok(not exists(select from app_private.whatsapp_preference_rate_buckets where bucket_hash=repeat('9',64)),'expired technical buckets cleanup');
  perform pg_temp.denied('select public.check_whatsapp_preference_rate(''raw-token'',30,60)','22023','raw rate key forbidden');
  perform pg_temp.denied(format('select public.check_whatsapp_preference_rate(%L,101,60)',repeat('7',64)),'22023','rate configuration bounded');
  perform pg_temp.denied('update app_private.whatsapp_promotion_policy set window_days=0','23514','frequency policy bounded');
end$$;
set local role anon;
select pg_temp.denied('select public.revoke_whatsapp_promotion(repeat(''1'',64))','42501','anon SQL capability RPC denied');
select pg_temp.denied('select * from public.whatsapp_message_preference_tokens','42501','anon direct token reads denied');
reset role;
set local role authenticated;
select pg_temp.denied('select public.lookup_whatsapp_preference_token(repeat(''1'',64))','42501','authenticated internal lookup denied');
select pg_temp.denied('select * from app_private.whatsapp_promotion_policy','42501','authenticated direct policy denied');
reset role;
set local role service_role;
select pg_temp.ok(public.lookup_whatsapp_preference_token(repeat('1',64)) is null,'service-only lookup callable');
select pg_temp.denied('select * from app_private.whatsapp_promotion_policy','42501','service direct policy denied');
select pg_temp.denied('select * from app_private.whatsapp_preference_rate_buckets','42501','service direct technical counter denied');
reset role;
select count(*)||' preference SQL assertions GREEN' as result from checks;
rollback;
